import { describe, expect, test, vi } from "vitest";
import { createEmailDeliveryAdapter, evaluateEmailReleaseControl } from "@/server/email/provider";

describe("Story 13.4 provider release control (ATDD RED)", () => {
  test.skip("[P0][13.4-UNIT-001] permits only a synthetic sandbox envelope and persists one server-only provider outcome", async () => {
    const submit = vi.fn().mockResolvedValue({ providerMessageId: "sandbox-msg-13-4" });
    const adapter = createEmailDeliveryAdapter({ mode: "sandbox", submit });
    const result = await adapter.deliver({
      tenantId: "11111111-1111-4111-8111-111111111111",
      recipient: { kind: "synthetic", address: "sandbox-recipient@example.test" },
      template: { key: "quote-delivery", locale: "sv-SE", renderedBody: "Offert" },
      attachments: [],
    });
    expect(result).toEqual({ outcome: "sent", providerMessageId: "sandbox-msg-13-4" });
    expect(submit).toHaveBeenCalledTimes(1);
    expect(JSON.stringify(result)).not.toContain("sandbox-recipient@example.test");
    expect(JSON.stringify(result)).not.toContain("Offert");
  });

  test.skip("[P0][13.4-UNIT-002] treats missing, malformed, preview-only, and unapproved real-recipient release state as closed", () => {
    for (const control of [undefined, { mode: "preview" }, { mode: "real", ownerApproval: false }, { mode: "real", ownerApproval: "malformed" }]) {
      expect(evaluateEmailReleaseControl(control)).toMatchObject({ allowed: false, reason: expect.any(String) });
    }
  });
});

import { afterAll, beforeAll, describe, expect, test, vi } from "vitest";
import { createClient } from "@supabase/supabase-js";
import { adminQuery, closeAdminPool } from "../../factories/admin-sql";
import { cleanupFixture, createTwoTenantFixture } from "../../factories/tenants";
import { isLocalStackReachable, LOCAL_SUPABASE_SERVICE_ROLE_KEY, LOCAL_SUPABASE_URL } from "../../support/test-env";
import { skipUnlessStack } from "../../support/stack-gate";

let stackUp = false;
beforeAll(async () => { stackUp = await isLocalStackReachable(); });
afterAll(async () => { await closeAdminPool(); });

const deps = () => ({ client: createClient(LOCAL_SUPABASE_URL, LOCAL_SUPABASE_SERVICE_ROLE_KEY, { auth: { autoRefreshToken: false, persistSession: false } }) });

describe("Story 13.4 activated email outbox delivery (ATDD RED)", () => {
  test.skip("[P0][13.4-INT-001] sends one sandbox-eligible claim, stores only provider ID, and appends sent exactly once", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { processEmailOutbox } = await import("@/server/email/outbox");
    const fixture = await createTwoTenantFixture();
    const submit = vi.fn().mockResolvedValue({ providerMessageId: "sandbox-msg-13-4" });
    try {
      const row = (await adminQuery("insert into public.email_outbox (tenant_id,recipient_hash,category,subject_type,subject_id,logical_period,template_key,template_version,template_params,next_attempt_at) values ($1,repeat('a',64),'quote.delivery','quote',gen_random_uuid(),'2026-09-24','quote-delivery',1,'{}'::jsonb,now()-interval '1 minute') returning id", [fixture.tenantA.id]))[0]!;
      await processEmailOutbox({ ...deps(), deliveryAdapter: { submit }, releaseControl: { mode: "sandbox" } }, { tenantId: fixture.tenantA.id, workerId: "worker-13-4" });
      expect(submit).toHaveBeenCalledOnce();
      expect(await adminQuery("select state, provider_message_id from public.email_outbox where id=$1", [row.id])).toEqual([{ state: "sent", provider_message_id: "sandbox-msg-13-4" }]);
      expect(await adminQuery("select event_type from public.email_delivery_events where outbox_id=$1 order by created_at", [row.id])).toEqual(expect.arrayContaining([{ event_type: "sent" }]));
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][13.4-INT-002] leaves eligible work queued and makes no adapter call while the release posture is closed", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { processEmailOutbox } = await import("@/server/email/outbox");
    const fixture = await createTwoTenantFixture();
    const submit = vi.fn();
    try {
      const row = (await adminQuery("insert into public.email_outbox (tenant_id,recipient_hash,category,subject_type,subject_id,logical_period,template_key,template_version,template_params,next_attempt_at) values ($1,repeat('b',64),'quote.delivery','quote',gen_random_uuid(),'2026-09-24','quote-delivery',1,'{}'::jsonb,now()-interval '1 minute') returning id", [fixture.tenantA.id]))[0]!;
      await processEmailOutbox({ ...deps(), deliveryAdapter: { submit }, releaseControl: { mode: "real", ownerApproval: false } }, { tenantId: fixture.tenantA.id, workerId: "worker-13-4" });
      expect(submit).not.toHaveBeenCalled();
      expect(await adminQuery("select state, provider_message_id from public.email_outbox where id=$1", [row.id])).toEqual([{ state: "queued", provider_message_id: null }]);
      expect(await adminQuery("select event_type from public.email_delivery_events where outbox_id=$1 and event_type='sent'", [row.id])).toEqual([]);
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][13.4-INT-003] suppresses matching non-essential email before rendering or provider submission while leaving other tenant/category rows eligible", async (ctx) => {
    if (skipUnlessStack(ctx, stackUp)) return;
    const { processEmailOutbox } = await import("@/server/email/outbox");
    const fixture = await createTwoTenantFixture();
    const submit = vi.fn();
    try {
      const row = (await adminQuery("insert into public.email_outbox (tenant_id,recipient_hash,category,subject_type,subject_id,logical_period,template_key,template_version,template_params,next_attempt_at) values ($1,repeat('c',64),'quote.follow_up_due','quote',gen_random_uuid(),'2026-09-24','quote-follow-up',1,'{}'::jsonb,now()-interval '1 minute') returning id,recipient_hash", [fixture.tenantA.id]))[0]!;
      await adminQuery("insert into public.email_suppressions (tenant_id,recipient_hash,category) values ($1,$2,'quote.follow_up_due')", [fixture.tenantA.id, row.recipient_hash]);
      await processEmailOutbox({ ...deps(), deliveryAdapter: { submit }, releaseControl: { mode: "sandbox" } }, { tenantId: fixture.tenantA.id, workerId: "worker-13-4" });
      expect(submit).not.toHaveBeenCalled();
      expect(await adminQuery("select state from public.email_outbox where id=$1", [row.id])).toEqual([{ state: "suppressed" }]);
    } finally { await cleanupFixture(fixture); }
  });
});

import { describe, expect, test, vi } from "vitest";
import { processQuoteDelivery } from "@/server/email/outbox";

describe("Story 13.4 quote-email attachment authority (ATDD RED)", () => {
  test.skip("[P0][13.4-INT-004] submits current authorized quote PDF bytes only and never constructs a public acceptance link", async () => {
    const submit = vi.fn().mockResolvedValue({ providerMessageId: "sandbox-quote-13-4" });
    const loadCurrentAuthorizedPdf = vi.fn().mockResolvedValue({ bytes: new Uint8Array([37, 80, 68, 70]), snapshotId: "snapshot-current" });
    await processQuoteDelivery({ releaseControl: { mode: "sandbox" }, loadCurrentAuthorizedPdf, deliveryAdapter: { submit } }, { tenantId: "11111111-1111-4111-8111-111111111111", quoteId: "22222222-2222-4222-8222-222222222222" });
    expect(submit).toHaveBeenCalledWith(expect.objectContaining({ attachments: [expect.objectContaining({ bytes: new Uint8Array([37, 80, 68, 70]) })] }));
    expect(JSON.stringify(submit.mock.calls)).not.toMatch(/accept|public|signedUrl/i);
  });

  test.skip("[P0][13.4-INT-005] rejects stale, invalid, or missing quote PDFs before provider submission and keeps the item recoverably queued", async () => {
    for (const pdf of [null, { bytes: new Uint8Array(), snapshotId: "stale", current: false }, { bytes: new Uint8Array([37]), snapshotId: "invalid", valid: false }]) {
      const submit = vi.fn();
      await expect(processQuoteDelivery({ releaseControl: { mode: "sandbox" }, loadCurrentAuthorizedPdf: async () => pdf, deliveryAdapter: { submit } }, { tenantId: "11111111-1111-4111-8111-111111111111", quoteId: "22222222-2222-4222-8222-222222222222" })).rejects.toMatchObject({ code: "QUOTE_PDF_UNAVAILABLE", recoverable: true });
      expect(submit).not.toHaveBeenCalled();
    }
  });

  test.skip("[P1][13.4-INT-006] prevents every terminal quote reminder state from enqueueing or submitting a reminder", async () => {
    for (const status of ["accepted", "rejected", "withdrawn", "superseded", "expired"]) {
      await expect(processQuoteDelivery({ releaseControl: { mode: "sandbox" } }, { tenantId: "11111111-1111-4111-8111-111111111111", quoteId: "22222222-2222-4222-8222-222222222222", kind: "reminder", quoteStatus: status })).resolves.toMatchObject({ outcome: "not_eligible" });
    }
  });
});

import { describe, expect, test } from "vitest";
import { createClient } from "@supabase/supabase-js";
import { createTwoTenantFixture, cleanupFixture } from "../../factories/tenants";
import { LOCAL_SUPABASE_ANON_KEY, LOCAL_SUPABASE_URL } from "../../support/test-env";

describe("Story 13.4 unsubscribe public capability and RLS (ATDD RED)", () => {
  test.skip("[P0][13.4-RLS-001] hashes a 256-bit token, limits its scope, and prevents tenant-B reads or mutation through tenant-A authority", async () => {
    const fixture = await createTwoTenantFixture();
    try {
      const { issueUnsubscribeToken, consumeUnsubscribeToken } = await import("@/server/email/unsubscribe");
      const issued = await issueUnsubscribeToken({ tenantId: fixture.tenantA.id, recipientHash: "a".repeat(64), category: "quote.follow_up_due", entropyBytes: 32 });
      expect(issued.plaintextToken).toHaveLength(64);
      expect(issued.persisted).toMatchObject({ tokenHash: expect.stringMatching(/^[a-f0-9]{64}$/), tenantId: fixture.tenantA.id, category: "quote.follow_up_due" });
      const outcome = await consumeUnsubscribeToken({ token: issued.plaintextToken, tenantId: fixture.tenantB.id });
      expect(outcome).toEqual({ state: "inactive" });
      const anon = createClient(LOCAL_SUPABASE_URL, LOCAL_SUPABASE_ANON_KEY);
      expect((await anon.from("email_unsubscribe_tokens").select("*")).data).toEqual([]);
    } finally { await cleanupFixture(fixture); }
  });

  test.skip("[P0][13.4-RLS-002] makes unknown and revoked tokens indistinguishable, returns 429 for token/IP fixed-window limits, and never emits tenant or recipient data", async () => {
    const { handleUnsubscribeRequest } = await import("@/server/email/unsubscribe");
    const unknown = await handleUnsubscribeRequest({ token: "0".repeat(64), ip: "203.0.113.15" });
    const revoked = await handleUnsubscribeRequest({ token: "1".repeat(64), ip: "203.0.113.15" });
    expect(unknown).toEqual(revoked);
    expect(unknown).toMatchObject({ status: 200, body: { state: "inactive" } });
    expect(JSON.stringify(unknown)).not.toMatch(/tenant|recipient|email/i);
    const limited = await handleUnsubscribeRequest({ token: "0".repeat(64), ip: "203.0.113.15", attemptsInWindow: 11 });
    expect(limited).toMatchObject({ status: 429, headers: { "retry-after": expect.any(String) } });
  });
});

import { describe, expect, test } from "vitest";
import { verifyServiceRoleContainment, verifyPublicRouteImports } from "@/../scripts/verify/check-service-role-containment";

describe("Story 13.4 delivery and public-shell containment (ATDD RED)", () => {
  test.skip("[P0][13.4-STATIC-001] allows the provider adapter only in server email modules and rejects credentials or adapter imports from client paths", async () => {
    const result = await verifyServiceRoleContainment({ root: process.cwd(), allowlist: ["src/server/email/provider.ts"] });
    expect(result.violations).toEqual([]);
    expect(result.allowedUsages).toEqual(["src/server/email/provider.ts"]);
  });

  test.skip("[P1][13.4-STATIC-002] keeps the public unsubscribe route free of app shell, tenant context, session, navigation, and provider imports", async () => {
    const result = await verifyPublicRouteImports({ root: process.cwd(), route: "src/app/(public)/unsubscribe" });
    expect(result.violations).toEqual([]);
    expect(result.imports).not.toEqual(expect.arrayContaining([expect.stringMatching(/app-shell|tenant-context|session|navigation|provider/i)]));
  });
});
